    65→export default function QuoteViewerPage() {
    66→  const params = useParams();
    67→  const search = useSearchParams();
    68→  const token = params?.token as string;
    69→  const debug = search?.get('debug') === '1';
    70→
    71→  const [loading, setLoading] = useState(true);
    72→  const [quoteData, setQuoteData] = useState<QuoteData | null>(null);
    73→  const [error, setError] = useState<string | null>(null);
    74→  const [loadingItems, setLoadingItems] = useState<Set<string>>(new Set());
    75→  interface DeleteConfirmationState {
    76→    isOpen: boolean;
    77→    itemId: string;
    78→    serviceName: string;
    79→  }
    80→
    81→  const [deleteConfirmation, setDeleteConfirmation] = useState<DeleteConfirmationState>({
    82→    isOpen: false,
    83→    itemId: '',
    84→    serviceName: ''
    85→  });
    86→  const [isServiceModalOpen, setIsServiceModalOpen] = useState(false);
    87→  const { toast } = useToast();
    88→
    89→  // Get existing service names for filtering
    90→  const existingServiceNames = quoteData?.lineItems?.map(item => item.service) || [];
    91→
    92→  // Hooks for service management
    93→  const { services, isLoading: servicesLoading, error: servicesError } = useServices(existingServiceNames);
    94→  const { isAdding, addService } = useAddService(
    95→    (serviceName: string, updatedData) => {
    96→      // Success callback
    97→      if (updatedData) {
    98→        setQuoteData(updatedData);
    99→      }
   100→      setIsServiceModalOpen(false);
   101→      toast({
   102→        title: "Success",
   103→        description: `${serviceName} added to your quote`,
   104→      });
   105→    },
   106→    (serviceName: string, error: string) => {
   107→      // Error callback
   108→      toast({
   109→        title: "Error",
   110→        description: error,
   111→        variant: "destructive",
   112→      });
   113→    }
   114→  );
   115→
   116→  // Calculate savings client-side from line items with chosen frequencies
   117→  const savings = useMemo(() => {
   118→    if (!quoteData?.lineItems) return 0;
   119→    const selectedItems = quoteData.lineItems.filter(item => item.chosenFrequency && item.chosenFrequency > 0);
   120→    const standardTotal = selectedItems.reduce((sum, item) => sum + (item.alaCarteRate * (item.chosenFrequency || 0)), 0);
   121→    const memberTotal = selectedItems.reduce((sum, item) => sum + (item.handldRate * (item.chosenFrequency || 0)), 0);
   122→    return standardTotal - memberTotal;
   123→  }, [quoteData?.lineItems]);
   124→
   125→  // Check if membership is available (3+ services)
   126→  const serviceCount = quoteData?.lineItems?.length || 0;
   127→  const membershipAvailable = serviceCount >= 3;
   128→  const servicesNeeded = Math.max(0, 3 - serviceCount);
   129→
   130→  useEffect(() => {
   131→    let mounted = true;
   132→    (async () => {
   133→      setLoading(true);
   134→      setError(null);
   135→      try {
   136→        if (!token) throw new Error('Missing token in URL.');
   137→        const data = await fetchQuote(token);
   138→        if (!mounted) return;
   139→        setQuoteData(data);
   140→      } catch (e: any) {
   141→        if (mounted) setError(e?.message || 'Failed to load quote');
   142→      } finally {
   143→        if (mounted) setLoading(false);
   144→      }
   145→    })();
   146→    return () => {
   147→      mounted = false;
   148→    };
   149→  }, [token]);
   150→
   151→  const handleFrequencyChange = async (itemId: string, frequency: number) => {
   152→    if (!quoteData) return;
   153→    
   154→    // Capture current state to avoid race conditions
   155→    const currentQuoteData = quoteData;
   156→    const originalItem = currentQuoteData.lineItems.find(item => item.id === itemId);
   157→    const originalFrequency = originalItem?.chosenFrequency;
   158→    
   159→    // Add item to loading state
