   161→    
   162→    try {
   163→      // Optimistically update the UI using captured state
   164→      const updatedLineItems = currentQuoteData.lineItems.map(item => 
   165→        item.id === itemId ? { ...item, chosenFrequency: frequency } : item
   166→      );
   167→      setQuoteData({ ...currentQuoteData, lineItems: updatedLineItems });
   168→      
   169→      const response = await fetch(`/api/quotes/${token}`, {
   170→        method: 'PUT',
   171→        headers: { 'Content-Type': 'application/json' },
   172→        body: JSON.stringify({
