    53→async function at(path, options = {}) {
    54→  const res = await fetch(`https://api.airtable.com/v0/${AIRTABLE_BASE_ID}/${path}`, {
    55→    ...options,
    56→    headers: {
    57→      Authorization: `Bearer ${AIRTABLE_API_KEY}`,
    58→      "Content-Type": "application/json",
    59→      ...(options.headers || {}),
    60→    },
    61→  });
    62→  const data = await res.json();
    63→  return { ok: res.ok, status: res.status, data };
    64→}
    65→
    66→// Resolve Quote Request record id by token
    67→async function quoteIdFromToken(token) {
    68→  const filter = encodeURIComponent(`{${QUOTE_TOKEN_FIELD}} = "${token}"`);
    69→  const { ok, status, data } = await at(
    70→    `${encodeURIComponent(QUOTES_TABLE)}?filterByFormula=${filter}&maxRecords=1`
    71→  );
    72→  if (!ok) throw new Error(`Airtable ${status}: ${data?.error?.message || "Quote lookup failed"}`);
    73→  return data?.records?.[0]?.id || null;
    74→}
