    76→// Read caches from Quote Request (Stories/SqFt/Lot)
    77→async function fetchQuoteCaches(quoteId) {
    78→  const { ok, status, data } = await at(`${encodeURIComponent(QUOTES_TABLE)}/${quoteId}`);
    79→  if (!ok) throw new Error(`Airtable ${status}: ${data?.error?.message || "Quote read failed"}`);
    80→  const f = data?.fields || {};
    81→  return {
    82→    stories: f[QUOTE_STORIES_FIELD] ?? "Any",
    83→    sqft:    f[QUOTE_SQFT_FIELD]    ?? "Any",
    84→    lot:     f[QUOTE_LOTSIZE_FIELD] ?? "Any",
    85→  };
    86→}
    87→
    88→function buildLookupKey(service, caches) {
    89→  // mirrors your Airtable formula for Lookup Key (cache)
    90→  return `${service} | ${caches.stories} | ${caches.sqft} | ${caches.lot}`;
    91→}
