   118→export async function POST(req, { params }) {
   119→  try {
   120→    if (!AIRTABLE_API_KEY || !AIRTABLE_BASE_ID) return bad(500, "Missing Airtable credentials");
   121→
   122→    const tokenFromUrl = params?.token;
   123→    const body = await req.json().catch(() => ({}));
