    27→    quoteId: fields['Quote ID'] || '',
    28→    token: fields['Token'] || '',
    29→    firstName: fields['First Name'] || '',
    30→    lastName: fields['Last Name'] || '',
    31→    email: fields['Email'] || '',
    32→    city: fields['City'] || '',
    33→    stories: fields['Stories'],
    34→    squareFootage: fields['Square Footage'],
    35→    lotSize: fields['Lot Size'],
    36→    alaCarteTotal: fields['A La Carte Total'] || 0,
    37→    handldTotal: fields['Handld Total'] || 0,
    38→    alaCarteTotalAnnual: fields['A La Carte Total Annual'],
    39→    handldTotalAnnual: fields['Handld Total Annual'],
    40→    selectedServices: fields['Selected Services'] || [],
    41→    createdAt: fields['Created At'] || record.createdTime,
    42→    updatedAt: fields['Updated At']
    43→  };
    44→}
    45→
    46→/**
    47→ * Maps our domain Quote model back to Airtable fields for updates
    48→ * Only includes fields that are defined (partial update)
    49→ */
    50→export function mapQuoteToAirtable(quote: Partial<Quote>): Partial<AirtableQuoteFields> {
    51→  const fields: Partial<AirtableQuoteFields> = {};
    52→  
    53→  if (quote.quoteId !== undefined) fields['Quote ID'] = quote.quoteId;
    54→  if (quote.token !== undefined) fields['Token'] = quote.token;
    55→  if (quote.firstName !== undefined) fields['First Name'] = quote.firstName;
    56→  if (quote.lastName !== undefined) fields['Last Name'] = quote.lastName;
    57→  if (quote.email !== undefined) fields['Email'] = quote.email;
    58→  if (quote.city !== undefined) fields['City'] = quote.city;
    59→  if (quote.stories !== undefined) fields['Stories'] = quote.stories;
    60→  if (quote.squareFootage !== undefined) fields['Square Footage'] = quote.squareFootage;
    61→  if (quote.lotSize !== undefined) fields['Lot Size'] = quote.lotSize;
    62→  if (quote.alaCarteTotal !== undefined) fields['A La Carte Total'] = quote.alaCarteTotal;
    63→  if (quote.handldTotal !== undefined) fields['Handld Total'] = quote.handldTotal;
    64→  if (quote.alaCarteTotalAnnual !== undefined) fields['A La Carte Total Annual'] = quote.alaCarteTotalAnnual;
    65→  if (quote.handldTotalAnnual !== undefined) fields['Handld Total Annual'] = quote.handldTotalAnnual;
    66→  if (quote.selectedServices !== undefined) fields['Selected Services'] = quote.selectedServices;
    67→  
    68→  return fields;
    69→}
    70→
    71→
    72→// ============================================
    73→// LineItem Mappers
    74→// ============================================
    75→
    76→/**
    77→ * Maps an Airtable line item record to our domain LineItem model
    78→ */
    79→export function mapAirtableToLineItem(record: AirtableLineItemRecord): LineItem {
    80→  const fields = record.fields;
    81→  
    82→  // Convert string frequency to number (e.g., "5" -> 5)
    83→  const frequency = fields['Chosen Frequency'] ? parseInt(fields['Chosen Frequency'], 10) : undefined;
    84→  
    85→  // Handle pricing fields - can be arrays or single values, and have different field names
    86→  let handldRate = 0;
    87→  let alaCarteRate = 0;
    88→  
    89→  // Try "Handld Price" first, then "Handld Rate"
    90→  if (fields['Handld Price'] !== undefined) {
    91→    handldRate = Array.isArray(fields['Handld Price']) 
    92→      ? fields['Handld Price'][0] || 0
    93→      : fields['Handld Price'] || 0;
    94→  } else if (fields['Handld Rate'] !== undefined) {
    95→    handldRate = fields['Handld Rate'] || 0;
    96→  }
    97→  
    98→  // Try "A La Carte Price" first, then "A La Carte Rate"
    99→  if (fields['A La Carte Price'] !== undefined) {
   100→    alaCarteRate = Array.isArray(fields['A La Carte Price'])
   101→      ? fields['A La Carte Price'][0] || 0
   102→      : fields['A La Carte Price'] || 0;
   103→  } else if (fields['A La Carte Rate'] !== undefined) {
   104→    alaCarteRate = fields['A La Carte Rate'] || 0;
   105→  }
   106→  
   107→  return {
   108→    id: record.id,
   109→    service: fields['Service'] || '',
   110→    description: fields['Description'],
