'use client';

import { useState } from 'react';
import type { Quote, LineItem } from '@/lib/airtable';

interface QuoteData {
  quote: Quote;
  lineItems: LineItem[];
}

interface AddServiceResponse {
  ok: boolean;
  created?: any;
  lookupKey?: string;
  pricingRuleLinked?: boolean;
}

interface UseAddServiceResult {
  isAdding: boolean;
  addService: (serviceName: string, token: string) => Promise<boolean>;
}

export function useAddService(
  onSuccess: (serviceName: string, updatedData?: QuoteData) => void,
  onError: (serviceName: string, error: string) => void
): UseAddServiceResult {
  const [isAdding, setIsAdding] = useState(false);

  const addService = async (serviceName: string, token: string): Promise<boolean> => {
    if (isAdding) return false;

    setIsAdding(true);

    try {
      const response = await fetch(`/api/quotes/${token}/items`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          serviceName,
          // Default quantity is 1 (handled by the API)
          // Frequency will be set to suggested frequency by the API
        })
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error || `Failed to add service: ${response.status}`);
      }

      const result: AddServiceResponse = await response.json();

      if (!result.ok) {
        throw new Error('Failed to add service');
      }

      // Fetch updated quote data to get the latest line items
      const updatedResponse = await fetch(`/api/quotes/${token}`, {
        cache: 'no-store'
      });

      let updatedData: QuoteData | undefined;
      if (updatedResponse.ok) {
        updatedData = await updatedResponse.json();
      }

      onSuccess(serviceName, updatedData);
      return true;
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to add service';
      onError(serviceName, errorMessage);
      return false;
    } finally {
      setIsAdding(false);
    }
  };

  return {
    isAdding,
    addService
  };
}

