'use client';

import { useState } from 'react';
import type { Quote, LineItem } from '@/lib/airtable';

interface QuoteData {
  quote: Quote;
  lineItems: LineItem[];
}

interface AddServiceResponse {
  ok: boolean;
  created?: any;
  lookupKey?: string;
  pricingRuleLinked?: boolean;
}

interface UseAddServiceResult {
  isAdding: boolean;
  addService: (serviceName: string, token: string) => Promise<boolean>;
}

export function useAddService(
  onSuccess: (serviceName: string, updatedData?: QuoteData) => void,
  onError: (serviceName: string, error: string) => void
): UseAddServiceResult {
  const [isAdding, setIsAdding] = useState(false);

  const addService = async (serviceName: string, token: string): Promise<boolean> => {
    if (isAdding) return false;

    setIsAdding(true);

    try {
      const response = await fetch(`/api/quotes/${token}/items`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          serviceName,
          // Default quantity is 1 (handled by the API)
          // Frequency will be set to suggested frequency by the API
        })
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error || `Failed to add service: ${response.status}`);
      }

      const result: AddServiceResponse = await response.json();

      if (!result.ok) {
        throw new Error('Failed to add service');
      }

      // Log for debugging
      if (!result.pricingRuleLinked) {
        console.warn(`No pricing rule found for service: ${serviceName}. Lookup key: ${result.lookupKey}`);
      }

      // Fetch updated quote data with retry logic for pricing data
      let updatedData: QuoteData | undefined;
      let retryCount = 0;
      const maxRetries = 3;

      while (retryCount < maxRetries) {
        // Add a small delay to allow Airtable lookup fields to populate
        if (retryCount > 0) {
          await new Promise(resolve => setTimeout(resolve, 1000 * retryCount)); // 1s, 2s delays
        }

        const updatedResponse = await fetch(`/api/quotes/${token}`, {
          cache: 'no-store'
        });

        if (updatedResponse.ok) {
          updatedData = await updatedResponse.json();

          // Debug: Log the frequency changes
          console.log(`Updated line items after adding service (attempt ${retryCount + 1}):`, updatedData.lineItems.map(item => ({
            service: item.service,
            frequency: item.chosenFrequency,
            id: item.id
          })));

          // Check if the newly added service has pricing data
          if (updatedData) {
            const newService = updatedData.lineItems.find(item => item.service === serviceName);
            if (newService && newService.handldRate > 0 && newService.alaCarteRate > 0) {
              // Pricing data is available, we can break out of the retry loop
              console.log(`Pricing data loaded for ${serviceName} on attempt ${retryCount + 1}`);
              break;
            } else if (newService) {
              console.warn(`Added service "${serviceName}" has missing pricing data on attempt ${retryCount + 1}. handldRate: ${newService.handldRate}, alaCarteRate: ${newService.alaCarteRate}`);
            }
          }
        }

        retryCount++;
      }

      onSuccess(serviceName, updatedData);
      return true;
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to add service';
      onError(serviceName, errorMessage);
      return false;
    } finally {
      setIsAdding(false);
    }
  };

  return {
    isAdding,
    addService
  };
}

