     6→
     7→// Helper function for setting up basic fetch mocks
     8→export const setupFetchMocks = (quoteData: any, services: string[] = []) => {
     9→  const mockFetch = global.fetch as jest.Mock;
    10→  mockFetch.mockImplementation((url: string) => {
    11→    if (url.includes('/api/quotes/') && url.includes('/items')) {
    12→      // POST request for adding service
    13→      return Promise.resolve({
    14→        ok: true,
    15→        json: async () => ({
    16→          ok: true,
    17→          created: { id: 'new-rec' },
    18→          pricingRuleLinked: true,
    19→        }),
    20→      });
    21→    } else if (url.includes('/api/quotes/')) {
    22→      return Promise.resolve({
    23→        ok: true,
    24→        json: async () => quoteData,
    25→      });
    26→    } else if (url.includes('/api/services')) {
    27→      return Promise.resolve({
    28→        ok: true,
    29→        json: async () => ({ services }),
    30→      });
    31→    }
    32→    return Promise.reject(new Error(`Unhandled URL: ${url}`));
    33→  });
    34→};
    35→
    36→// Helper for complex test with state changes (e.g., adding services)
    37→export const setupStatefulFetchMocks = (initialQuoteData: any, updatedQuoteData: any, services: string[] = []) => {
    38→  const mockFetch = global.fetch as jest.Mock;
    39→  let serviceAdded = false;
    40→  
    41→  mockFetch.mockImplementation((url: string) => {
    42→    if (url.includes('/api/quotes/') && url.includes('/items')) {
    43→      // POST request for adding service
    44→      serviceAdded = true;
    45→      return Promise.resolve({
    46→        ok: true,
    47→        json: async () => ({
    48→          ok: true,
    49→          created: { id: 'rec789' },
    50→          pricingRuleLinked: true,
    51→        }),
    52→      });
    53→    } else if (url.includes('/api/quotes/')) {
    54→      // Return updated data after service has been added
    55→      const dataToReturn = serviceAdded ? updatedQuoteData : initialQuoteData;
    56→      return Promise.resolve({
    57→        ok: true,
    58→        json: async () => dataToReturn,
    59→      });
    60→    } else if (url.includes('/api/services')) {
    61→      return Promise.resolve({
    62→        ok: true,
    63→        json: async () => ({ services }),
    64→      });
    65→    }
    66→    return Promise.reject(new Error(`Unhandled URL: ${url}`));
    67→  });
    68→};
    69→
    70→// Helper for testing API update operations (PUT requests)
    71→export const setupUpdateFetchMocks = (quoteData: any, updateSuccess: boolean = true, updateResponse?: any) => {
    72→  const mockFetch = global.fetch as jest.Mock;
    73→  
    74→  mockFetch.mockImplementation((url: string, options?: any) => {
    75→    if (url.includes('/api/quotes/') && options?.method === 'PUT') {
    76→      // PUT request for updating quote/line items
    77→      return Promise.resolve({
    78→        ok: updateSuccess,
    79→        json: async () => updateResponse || (updateSuccess ? { ok: true } : { error: 'Update failed' }),
    80→      });
    81→    } else if (url.includes('/api/quotes/')) {
