/**
 * @jest-environment jsdom
 * @fileoverview Shared test helpers for fetch mocking across quote viewer tests
 * This file contains utility functions and should not be run as a test suite
 */

// Helper function for setting up basic fetch mocks
export const setupFetchMocks = (quoteData: any, services: string[] = []) => {
  const mockFetch = global.fetch as jest.Mock;
  mockFetch.mockImplementation((url: string) => {
    if (url.includes('/api/quotes/') && url.includes('/items')) {
      // POST request for adding service
      return Promise.resolve({
        ok: true,
        json: async () => ({
          ok: true,
          created: { id: 'new-rec' },
          pricingRuleLinked: true,
        }),
      });
    } else if (url.includes('/api/quotes/')) {
      return Promise.resolve({
        ok: true,
        json: async () => quoteData,
      });
    } else if (url.includes('/api/services')) {
      return Promise.resolve({
        ok: true,
        json: async () => ({ services }),
      });
    }
    return Promise.reject(new Error(`Unhandled URL: ${url}`));
  });
};

// Helper for complex test with state changes (e.g., adding services)
export const setupStatefulFetchMocks = (initialQuoteData: any, updatedQuoteData: any, services: string[] = []) => {
  const mockFetch = global.fetch as jest.Mock;
  let serviceAdded = false;

  mockFetch.mockImplementation((url: string) => {
    if (url.includes('/api/quotes/') && url.includes('/items')) {
      // POST request for adding service
      serviceAdded = true;
      return Promise.resolve({
        ok: true,
        json: async () => ({
          ok: true,
          created: { id: 'rec789' },
          pricingRuleLinked: true,
        }),
      });
    } else if (url.includes('/api/quotes/')) {
      // Return updated data after service has been added
      const dataToReturn = serviceAdded ? updatedQuoteData : initialQuoteData;
      return Promise.resolve({
        ok: true,
        json: async () => dataToReturn,
      });
    } else if (url.includes('/api/services')) {
      return Promise.resolve({
        ok: true,
        json: async () => ({ services }),
      });
    }
    return Promise.reject(new Error(`Unhandled URL: ${url}`));
  });
};

// Helper for testing API update operations (PUT requests)
export const setupUpdateFetchMocks = (quoteData: any, updateSuccess: boolean = true, updateResponse?: any) => {
  const mockFetch = global.fetch as jest.Mock;

  mockFetch.mockImplementation((url: string, options?: any) => {
    if (url.includes('/api/quotes/') && options?.method === 'PUT') {
      // PUT request for updating quote/line items
      return Promise.resolve({
        ok: updateSuccess,
        json: async () => updateResponse || (updateSuccess ? { ok: true } : { error: 'Update failed' }),
      });
    } else if (url.includes('/api/quotes/')) {
      // GET request for quote data
      return Promise.resolve({
        ok: true,
        json: async () => quoteData,
      });
    } else if (url.includes('/api/services')) {
      return Promise.resolve({
        ok: true,
        json: async () => ({ services: [] }),
      });
    }
    return Promise.reject(new Error(`Unhandled URL: ${url}`));
  });
};

