import React from 'react';
import { render, screen, fireEvent, waitFor, act } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import QuoteViewerPage from '../page';
import { useToast } from '@/components/ui/use-toast';
import { setupFetchMocks, setupUpdateFetchMocks, setupErrorFetchMocks, setupDelayedUpdateFetchMocks, setupCustomFetchMock } from '../test-helpers';

// Mock window.location
delete (window as any).location;
(window as any).location = {
  href: '',
  origin: 'http://localhost:3000'
};

// Mock dependencies
jest.mock('next/navigation', () => ({
  useParams: jest.fn(),
  useSearchParams: jest.fn(),
}));

jest.mock('@/components/ui/use-toast', () => ({
  useToast: jest.fn(),
}));

jest.mock('../../../components/LineItemsTable', () => {
  return function MockLineItemsTable({ 
    lineItems, 
    loadingItems, 
    onFrequencyChange,
    onRemoveItem
  }: any) {
    return (
      <div data-testid="line-items-table">
        {lineItems.map((item: any) => (
          <div key={item.id}>
            <span>{item.service}</span>
            <button 
              onClick={() => onFrequencyChange?.(item.id, 3)}
              disabled={loadingItems?.has(item.id)}
            >
              Change Frequency
            </button>
            <button 
              onClick={() => onRemoveItem?.(item.id)}
              disabled={loadingItems?.has(item.id)}
            >
              Remove
            </button>
            {loadingItems?.has(item.id) && <span>Loading...</span>}
          </div>
        ))}
      </div>
    );
  };
});

jest.mock('@/components/ui/cta-banner', () => ({
  CTABanner: ({ message }: { message: string }) => <div data-testid="cta-banner">{message}</div>,
}));

// Mock fetch
global.fetch = jest.fn();

describe('QuoteViewerPage - Membership Requirements', () => {
  const mockToast = jest.fn();
  const mockQuoteDataWithTwoServices = {
    quote: {
      id: 'rec123',
      quoteId: 'Q-001',
      firstName: 'John',
      lastName: 'Doe',
      email: 'john@example.com',
      city: 'San Francisco',
      stories: '2',
      squareFootage: '2000',
      lotSize: 'Medium',
    },
    lineItems: [
      { id: 'line1', service: 'Service 1', alaCarteRate: 100, handldRate: 70, chosenFrequency: 1 },
      { id: 'line2', service: 'Service 2', alaCarteRate: 150, handldRate: 105, chosenFrequency: 2 },
    ],
  };

  const mockQuoteDataWithThreeServices = {
    quote: {
      id: 'rec123',
      quoteId: 'Q-001',
      firstName: 'John',
      lastName: 'Doe',
      email: 'john@example.com',
      city: 'San Francisco',
      stories: '2',
      squareFootage: '2000',
      lotSize: 'Medium',
    },
    lineItems: [
      { id: 'line1', service: 'Service 1', alaCarteRate: 100, handldRate: 70, chosenFrequency: 1 },
      { id: 'line2', service: 'Service 2', alaCarteRate: 150, handldRate: 105, chosenFrequency: 2 },
      { id: 'line3', service: 'Service 3', alaCarteRate: 200, handldRate: 140, chosenFrequency: 1 },
    ],
  };

  beforeEach(() => {
    jest.clearAllMocks();
    (useToast as jest.Mock).mockReturnValue({ toast: mockToast });
    const { useParams, useSearchParams } = require('next/navigation');
    useParams.mockReturnValue({ token: 'test-token' });
    useSearchParams.mockReturnValue({ get: () => null });
  });

  describe('CTA Banner and Membership Button', () => {
    it('should show CTA banner and disable membership button with less than 3 services', async () => {
      setupFetchMocks(mockQuoteDataWithTwoServices);

      render(<QuoteViewerPage />);

      await waitFor(() => {
        // Check CTA banner is shown with dynamic message
        const ctaBanner = screen.getByTestId('cta-banner');
        expect(ctaBanner).toBeInTheDocument();
        expect(ctaBanner).toHaveTextContent('Add 1 more service to unlock Handld Membership and save 30%!');

        // Check membership button is disabled with informative text
        const membershipButton = screen.getByText('Membership requires 3+ services');
        expect(membershipButton).toBeDisabled();
        expect(membershipButton).toHaveClass('cursor-not-allowed');
        expect(membershipButton).toHaveClass('opacity-60');

        // Check Add Service button exists (no special styling when < 3 services)
        const addServiceButton = screen.getByText('Add Service');
        expect(addServiceButton.closest('button')).toBeInTheDocument();
      });
    });

    it('should hide CTA banner and enable membership button with 3 or more services', async () => {
      setupFetchMocks(mockQuoteDataWithThreeServices);

      render(<QuoteViewerPage />);

      await waitFor(() => {
        // Check CTA banner is NOT shown
        expect(screen.queryByTestId('cta-banner')).not.toBeInTheDocument();

        // Check membership button is enabled
        const membershipButton = screen.getByText(/Book Handld Membership/);
        expect(membershipButton).not.toBeDisabled();
        expect(membershipButton).toHaveClass('cursor-pointer');
        expect(membershipButton).not.toHaveClass('opacity-60');

        // Check Add Service button exists (no special styling when >= 3 services)
        const addServiceButton = screen.getByText('Add Service');
        expect(addServiceButton.closest('button')).toBeInTheDocument();

        // Check savings display is shown and CTA banner is hidden
        expect(screen.queryByTestId('cta-banner')).not.toBeInTheDocument();
      });
    });

    it('should show correct messaging for single service needed', async () => {
      const oneServiceData = {
        ...mockQuoteDataWithThreeServices,
        lineItems: mockQuoteDataWithThreeServices.lineItems.slice(0, 2),
      };

      setupFetchMocks(oneServiceData);

      render(<QuoteViewerPage />);

      await waitFor(() => {
        // CTA banner should be present
        expect(screen.getByTestId('cta-banner')).toBeInTheDocument();
      });
    });

    it('should show correct messaging for multiple services needed', async () => {
      const noServiceData = {
        ...mockQuoteDataWithThreeServices,
        lineItems: [],
      };

      setupFetchMocks(noServiceData);

      render(<QuoteViewerPage />);

      await waitFor(() => {
        // CTA banner should be present
        expect(screen.getByTestId('cta-banner')).toBeInTheDocument();
      });
    });
  });
});

describe('QuoteViewerPage - Frequency Update', () => {
  const mockToast = jest.fn();
  const mockQuoteData = {
    quote: {
      id: 'rec123',
      quoteId: 'Q-001',
      firstName: 'John',
      lastName: 'Doe',
      email: 'john@example.com',
      city: 'Austin',
      stories: '2',
      squareFootage: '2500',
      lotSize: '0.25 acres',
    },
    lineItems: [
      {
        id: 'rec1',
        service: 'Lawn Mowing',
        alaCarteRate: 100,
        handldRate: 70,
        chosenFrequency: 2,
        requestLink: ['req1'],
      },
      {
        id: 'rec2',
        service: 'Pool Cleaning',
        alaCarteRate: 150,
        handldRate: 105,
        chosenFrequency: 4,
        requestLink: ['req1'],
      },
    ],
  };

  beforeEach(() => {
    jest.clearAllMocks();

    (useToast as jest.Mock).mockReturnValue({ toast: mockToast });

    const mockUseParams = require('next/navigation').useParams;
    const mockUseSearchParams = require('next/navigation').useSearchParams;

    mockUseParams.mockReturnValue({ token: 'test-token' });
    mockUseSearchParams.mockReturnValue(new URLSearchParams());
  });

  it('handles successful frequency update', async () => {
    setupUpdateFetchMocks(mockQuoteData, true);

    render(<QuoteViewerPage />);

    // Wait for data to load
    await waitFor(() => {
      expect(screen.getByText('Lawn Mowing')).toBeInTheDocument();
    });

    // Click to change frequency
    const changeButtons = screen.getAllByText('Change Frequency');

    await act(async () => {
      fireEvent.click(changeButtons[0]);
    });

    // Wait for the update to complete
    await waitFor(() => {
      expect(mockToast).toHaveBeenCalledWith({
        title: 'Success',
        description: 'Frequency updated successfully',
      });
    });

    // Verify API was called with correct data
    expect(global.fetch).toHaveBeenCalledWith(
      '/api/quotes/test-token',
      {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          lineItems: [{ id: 'rec1', chosenFrequency: 3 }],
        }),
      }
    );
  });

  it('handles failed frequency update with rollback', async () => {
    setupUpdateFetchMocks(mockQuoteData, false, { error: 'Update failed' });

    render(<QuoteViewerPage />);

    // Wait for data to load
    await waitFor(() => {
      expect(screen.getByText('Lawn Mowing')).toBeInTheDocument();
    });

    // Click to change frequency
    const changeButtons = screen.getAllByText('Change Frequency');

    await act(async () => {
      fireEvent.click(changeButtons[0]);
    });

    // Wait for the error handling
    await waitFor(() => {
      expect(mockToast).toHaveBeenCalledWith({
        title: 'Error',
        description: 'Failed to update frequency. Please try again.',
        variant: 'destructive',
      });
    });
  });

  it('shows loading state during frequency update', async () => {
    const { resolveUpdate } = setupDelayedUpdateFetchMocks(mockQuoteData);

    render(<QuoteViewerPage />);

    // Wait for data to load
    await waitFor(() => {
      expect(screen.getByText('Lawn Mowing')).toBeInTheDocument();
    });

    // Click to change frequency
    const changeButtons = screen.getAllByText('Change Frequency');

    act(() => {
      fireEvent.click(changeButtons[0]);
    });

    // Check loading state is shown
    await waitFor(() => {
      expect(screen.getByText('Loading...')).toBeInTheDocument();
    });

    // Resolve the promise
    act(() => {
      resolveUpdate({
        ok: true,
        json: async () => ({ ok: true }),
      });
    });

    // Wait for loading to complete
    await waitFor(() => {
      expect(screen.queryByText('Loading...')).not.toBeInTheDocument();
    });
  });

  it('handles network errors gracefully', async () => {
    // First setup for initial load, then setup for error on update
    setupFetchMocks(mockQuoteData);

    render(<QuoteViewerPage />);

    // Wait for data to load
    await waitFor(() => {
      expect(screen.getByText('Lawn Mowing')).toBeInTheDocument();
    });

    // Setup network error for update
    setupErrorFetchMocks('network');

    // Click to change frequency
    const changeButtons = screen.getAllByText('Change Frequency');

    await act(async () => {
      fireEvent.click(changeButtons[0]);
    });

    // Wait for error toast
    await waitFor(() => {
      expect(mockToast).toHaveBeenCalledWith({
        title: 'Error',
        description: 'Failed to update frequency. Please try again.',
        variant: 'destructive',
      });
    });
  });

  it('performs optimistic updates', async () => {
    const { resolveUpdate } = setupDelayedUpdateFetchMocks(mockQuoteData);

    const { rerender } = render(<QuoteViewerPage />);

    // Wait for data to load
    await waitFor(() => {
      expect(screen.getByText('Lawn Mowing')).toBeInTheDocument();
    });

    // Click to change frequency
    const changeButtons = screen.getAllByText('Change Frequency');

    act(() => {
      fireEvent.click(changeButtons[0]);
    });

    // The component should optimistically update immediately
    // (In a real test, we'd check the actual frequency value displayed)

    // Resolve with success
    await act(async () => {
      resolveUpdate({
        ok: true,
        json: async () => ({ ok: true }),
      });
    });

    // Verify success toast
    await waitFor(() => {
      expect(mockToast).toHaveBeenCalledWith(
        expect.objectContaining({
          title: 'Success',
        })
      );
    });
  });

  it('reverts optimistic update on failure', async () => {
    setupUpdateFetchMocks(mockQuoteData, false, { error: 'Update failed' });

    render(<QuoteViewerPage />);

    // Wait for data to load
    await waitFor(() => {
      expect(screen.getByText('Lawn Mowing')).toBeInTheDocument();
    });

    // Click to change frequency
    const changeButtons = screen.getAllByText('Change Frequency');

    await act(async () => {
      fireEvent.click(changeButtons[0]);
    });

    // Wait for error and rollback
    await waitFor(() => {
      expect(mockToast).toHaveBeenCalledWith({
        title: 'Error',
        description: 'Failed to update frequency. Please try again.',
        variant: 'destructive',
      });
    });

    // The component should have reverted the change
    // (verified through the component state restoration logic)
  });

  it('handles multiple simultaneous updates', async () => {
    // Track update count using the shared helper
    let updateCount = 0;

    setupCustomFetchMock({
      quoteData: mockQuoteData,
      services: [],
      onUpdate: async (url: string, options: any) => {
        updateCount++;
        return Promise.resolve({
          ok: true,
          json: async () => ({ ok: true }),
        });
      }
    });

    render(<QuoteViewerPage />);

    // Wait for data to load
    await waitFor(() => {
      expect(screen.getByText('Pool Cleaning')).toBeInTheDocument();
    });

    // Click to change frequency on both items
    const changeButtons = screen.getAllByText('Change Frequency');

    await act(async () => {
      fireEvent.click(changeButtons[0]);
      fireEvent.click(changeButtons[1]);
    });

    // Wait for updates to complete
    await waitFor(() => {
      expect(updateCount).toBe(2);
    });

    // Verify both updates triggered toasts
    expect(mockToast).toHaveBeenCalledWith(
      expect.objectContaining({
        title: 'Success',
      })
    );
  });
});

