        const membershipButton = screen.getByText('Membership requires 3+ services');
        expect(membershipButton).toBeDisabled();
      });

      const membershipButton = screen.getByText('Membership requires 3+ services');
      fireEvent.click(membershipButton);

      // Should not redirect when disabled
      expect(mockAssign).not.toHaveBeenCalled();
    });
  });

  describe('A La Carte Booking Button', () => {
    it('should redirect to correct Stripe URL with price when clicked', async () => {
      setupFetchMocks(mockQuoteDataWithServices);

      render(<QuoteViewerPage />);

      await waitFor(() => {
        const alaCarteButton = screen.getByText(/Book with Standard Pricing/);
        expect(alaCarteButton).toBeInTheDocument();
        expect(alaCarteButton).not.toBeDisabled();
      });

      const alaCarteButton = screen.getByText(/Book with Standard Pricing/);
      fireEvent.click(alaCarteButton);

      // Calculate expected price: (100*1 + 150*2 + 200*1) * 100 = 60000 cents
      expect(mockAssign).toHaveBeenCalledWith(
        expect.stringMatching(/^https:\/\/buy\.stripe\.com\/9B600j2J85s79dI5tc7wA02\?/)
      );
      const calledUrl = mockAssign.mock.calls[0][0];
      expect(calledUrl).toContain('success_url=http%3A//localhost%3A3000/q/test-token%3Fsuccess%3Dalacarte');
      expect(calledUrl).toContain('cancel_url=http%3A//localhost%3A3000/q/test-token%3Fcancelled%3Dtrue');
      expect(calledUrl).toContain('amount=60000');
    });

    it('should show total price in button text', async () => {
      setupFetchMocks(mockQuoteDataWithServices);

      render(<QuoteViewerPage />);

      await waitFor(() => {
        const alaCarteButton = screen.getByText('Book with Standard Pricing — $600');
        expect(alaCarteButton).toBeInTheDocument();
      });
    });

    it('should be disabled when no services have frequencies selected', async () => {
      setupFetchMocks(mockQuoteDataNoFrequencies);

      render(<QuoteViewerPage />);

      await waitFor(() => {
        const alaCarteButton = screen.getByText('Select services to book');
        expect(alaCarteButton).toBeDisabled();
      });

      const alaCarteButton = screen.getByText('Select services to book');
      fireEvent.click(alaCarteButton);

      // Should not redirect when disabled
      expect(mockAssign).not.toHaveBeenCalled();
    });

    it('should handle zero total correctly', async () => {
      const zeroTotalData = {
        ...mockQuoteDataWithServices,
        lineItems: mockQuoteDataWithServices.lineItems.map(item => ({ 
          ...item, 
          chosenFrequency: 0,
          alaCarteRate: 0 
        }))
      };

      setupFetchMocks(zeroTotalData);

      render(<QuoteViewerPage />);

      await waitFor(() => {
        const alaCarteButton = screen.getByText('Select services to book');
        expect(alaCarteButton).toBeDisabled();
      });
    });
  });

  describe('Callback URLs', () => {
    it('should use current token in success and cancel URLs', async () => {
      const { useParams } = require('next/navigation');
      useParams.mockReturnValue({ token: 'custom-token-123' });

      setupFetchMocks(mockQuoteDataWithServices);

      render(<QuoteViewerPage />);

      await waitFor(() => {
        const membershipButton = screen.getByText(/Book Handld Membership/);
        expect(membershipButton).not.toBeDisabled();
      });

      const membershipButton = screen.getByText(/Book Handld Membership/);
      fireEvent.click(membershipButton);

      expect(window.location.href).toContain('success_url=http%3A//localhost%3A3000/q/custom-token-123%3Fsuccess%3Dmember');
      expect(window.location.href).toContain('cancel_url=http%3A//localhost%3A3000/q/custom-token-123%3Fcancelled%3Dtrue');
    });
  });
});

