    useSearchParams.mockReturnValue({ get: () => null });

    // Mock window.location.href assignment
    mockAssign = jest.fn();
    Object.defineProperty(window, 'location', {
      value: {
        href: '',
        origin: 'http://localhost:3000',
        assign: mockAssign
      },
      writable: true
    });

    // Override href setter
    let currentHref = '';
    Object.defineProperty(window.location, 'href', {
      get: () => currentHref,
      set: (value) => {
        currentHref = value;
        mockAssign(value);
      }
    });
  });

  describe('Member Booking Button', () => {
    it('should redirect to correct Stripe URL when clicked with 3+ services', async () => {
      setupFetchMocks(mockQuoteDataWithServices);

