      {
        id: 'rec1',
        service: 'Lawn Mowing',
        alaCarteRate: 100,
        handldRate: 70,
        chosenFrequency: 2,
        requestLink: ['req1'],
      },
      {
        id: 'rec2',
        service: 'Pool Cleaning',
        alaCarteRate: 150,
        handldRate: 105,
        chosenFrequency: 4,
        requestLink: ['req1'],
      },
