    useSearchParams.mockReturnValue({ get: () => null });

    // Mock window.location.href assignment
    mockAssign = jest.fn();

    // Store original location
    const originalLocation = window.location;

    // Create a new location object with mocked href
    const mockLocation = {
      ...originalLocation,
      href: '',
      origin: 'http://localhost:3000',
      assign: mockAssign
    };

    // Mock href setter
    Object.defineProperty(mockLocation, 'href', {
      get: () => mockLocation._href || '',
      set: (value) => {
        mockLocation._href = value;
        mockAssign(value);
      }
    });

    // Replace window.location
    Object.defineProperty(window, 'location', {
      value: mockLocation,
      writable: true,
      configurable: true
    });
  });

  describe('Member Booking Button', () => {
    it('should redirect to correct Stripe URL when clicked with 3+ services', async () => {
      setupFetchMocks(mockQuoteDataWithServices);

      render(<QuoteViewerPage />);

