        // Check Add Service button exists (no special styling when >= 3 services)
        const addServiceButton = screen.getByText('Add Service');
        expect(addServiceButton.closest('button')).toBeInTheDocument();

        // Check savings display is shown and CTA banner is hidden
        expect(screen.queryByTestId('cta-banner')).not.toBeInTheDocument();
      });
