import { renderHook, waitFor, act } from '@testing-library/react';
import { useAddService } from '../useAddService';

// Mock fetch globally
const mockFetch = jest.fn();
global.fetch = mockFetch;

// Mock data
const mockQuoteData = {
  quote: {
    id: 'rec123',
    quoteId: 'Q-001',
    token: 'test-token',
    firstName: 'John',
    lastName: 'Doe',
    email: 'john@example.com',
    city: 'Test City',
    alaCarteTotal: 200,
    handldTotal: 140,
  },
  lineItems: [
    {
      id: 'rec456',
      service: 'Window Washing',
      handldRate: 70,
      alaCarteRate: 100,
      chosenFrequency: 1,
      quoteId: 'Q-001',
    },
    {
      id: 'rec789',
      service: 'Gutter Cleaning',
      handldRate: 80,
      alaCarteRate: 120,
      chosenFrequency: 1,
      quoteId: 'Q-001',
    },
  ],
};

describe('useAddService', () => {
  const mockOnSuccess = jest.fn();
  const mockOnError = jest.fn();

  beforeEach(() => {
    jest.clearAllMocks();
    mockFetch.mockReset();
  });

  afterEach(() => {
    jest.restoreAllMocks();
  });

  describe('Successful service addition', () => {
    it('should add service successfully and refetch quote data', async () => {
      const serviceName = 'Gutter Cleaning';
      const token = 'test-token';

      // Mock successful add service response
      mockFetch.mockResolvedValueOnce({
        ok: true,
        json: async () => ({
          ok: true,
          created: { id: 'rec789' },
          lookupKey: 'Gutter Cleaning | 2 | 1000-2000 | Small',
          pricingRuleLinked: true,
        }),
      });

      // Mock successful refetch quote data response with the new service
      const updatedQuoteData = {
        ...mockQuoteData,
        lineItems: [
          ...mockQuoteData.lineItems,
          {
            id: 'rec789',
            service: serviceName,
            handldRate: 80,
            alaCarteRate: 120,
            chosenFrequency: 1,
            quoteId: 'Q-001',
          },
        ],
      };

      mockFetch.mockResolvedValueOnce({
        ok: true,
        json: async () => updatedQuoteData,
      });

      const { result } = renderHook(() => useAddService(mockOnSuccess, mockOnError));

      expect(result.current.isAdding).toBe(false);

      let success: boolean = false;
      await act(async () => {
        success = await result.current.addService(serviceName, token);
      });

      expect(success!).toBe(true);
      expect(result.current.isAdding).toBe(false);

      // Verify API calls
      expect(mockFetch).toHaveBeenCalledTimes(2);
      expect(mockFetch).toHaveBeenNthCalledWith(1, '/api/quotes/test-token/items', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          serviceName,
        }),
      });
      expect(mockFetch).toHaveBeenNthCalledWith(2, '/api/quotes/test-token', {
        cache: 'no-store',
      });

      // Verify callbacks
      expect(mockOnSuccess).toHaveBeenCalledWith(serviceName, updatedQuoteData);
      expect(mockOnError).not.toHaveBeenCalled();
    });

    it('should handle successful add without refetch data', async () => {
      const serviceName = 'Pressure Washing';
      const token = 'test-token';

      // Mock successful add service response
      mockFetch.mockResolvedValueOnce({
        ok: true,
        json: async () => ({ ok: true }),
      });

      // Mock failed refetch (not critical)
      mockFetch.mockResolvedValueOnce({
        ok: false,
        status: 404,
      });

      const { result } = renderHook(() => useAddService(mockOnSuccess, mockOnError));

      const success = await result.current.addService(serviceName, token);

      expect(success).toBe(true);
      expect(mockOnSuccess).toHaveBeenCalledWith(serviceName, undefined);
      expect(mockOnError).not.toHaveBeenCalled();
    });
  });

  describe('Error handling', () => {
    it('should handle HTTP error responses', async () => {
      const serviceName = 'Gutter Cleaning';
      const token = 'test-token';

      mockFetch.mockResolvedValueOnce({
        ok: false,
        status: 500,
        json: async () => ({ error: 'Server error' }),
      });

      const { result } = renderHook(() => useAddService(mockOnSuccess, mockOnError));

      const success = await result.current.addService(serviceName, token);

      expect(success).toBe(false);
      expect(result.current.isAdding).toBe(false);
      expect(mockOnSuccess).not.toHaveBeenCalled();
      expect(mockOnError).toHaveBeenCalledWith(serviceName, 'Server error');
    });

    it('should handle HTTP error without error message', async () => {
      const serviceName = 'Window Washing';
      const token = 'test-token';

      mockFetch.mockResolvedValueOnce({
        ok: false,
        status: 400,
        json: async () => ({}),
      });

      const { result } = renderHook(() => useAddService(mockOnSuccess, mockOnError));

      const success = await result.current.addService(serviceName, token);

      expect(success).toBe(false);
      expect(mockOnError).toHaveBeenCalledWith(serviceName, 'Failed to add service: 400');
    });

    it('should handle API response with ok: false', async () => {
      const serviceName = 'Pest Control';
      const token = 'test-token';

      mockFetch.mockResolvedValueOnce({
        ok: true,
        json: async () => ({ ok: false }),
      });

      const { result } = renderHook(() => useAddService(mockOnSuccess, mockOnError));

      const success = await result.current.addService(serviceName, token);

      expect(success).toBe(false);
      expect(mockOnError).toHaveBeenCalledWith(serviceName, 'Failed to add service');
    });

    it('should handle network errors', async () => {
      const serviceName = 'Handyman';
      const token = 'test-token';

      mockFetch.mockRejectedValueOnce(new Error('Network error'));

      const { result } = renderHook(() => useAddService(mockOnSuccess, mockOnError));

      const success = await result.current.addService(serviceName, token);

      expect(success).toBe(false);
      expect(mockOnError).toHaveBeenCalledWith(serviceName, 'Network error');
    });

    it('should handle JSON parsing errors', async () => {
      const serviceName = 'Trash Bin Cleaning';
      const token = 'test-token';

      mockFetch.mockResolvedValueOnce({
        ok: false,
        status: 400,
        json: async () => {
          throw new Error('Invalid JSON');
        },
      });

      const { result } = renderHook(() => useAddService(mockOnSuccess, mockOnError));

      const success = await result.current.addService(serviceName, token);

      expect(success).toBe(false);
      expect(mockOnError).toHaveBeenCalledWith(serviceName, 'Failed to add service: 400');
    });

    it('should handle unknown errors', async () => {
      const serviceName = 'Window Washing';
      const token = 'test-token';

      mockFetch.mockRejectedValueOnce('Unknown error');

      const { result } = renderHook(() => useAddService(mockOnSuccess, mockOnError));

      const success = await result.current.addService(serviceName, token);

      expect(success).toBe(false);
      expect(mockOnError).toHaveBeenCalledWith(serviceName, 'Failed to add service');
    });
  });

  describe('Loading state management', () => {
    it('should set isAdding to true during service addition', async () => {
      const serviceName = 'Window Washing';
      const token = 'test-token';

      let resolveAddService: (value: any) => void = () => {};
      const addServicePromise = new Promise(resolve => {
        resolveAddService = resolve;
      });

      mockFetch.mockReturnValueOnce(addServicePromise);

      const { result } = renderHook(() => useAddService(mockOnSuccess, mockOnError));

      expect(result.current.isAdding).toBe(false);

      const addPromise = result.current.addService(serviceName, token);

      // Wait for state update
      await waitFor(() => {
        expect(result.current.isAdding).toBe(true);
      });

      // Resolve the promise
      resolveAddService({
        ok: true,
        json: async () => ({ ok: true }),
      });

      await addPromise;

      // Should not be adding anymore
      await waitFor(() => {
        expect(result.current.isAdding).toBe(false);
      });
    });

    it('should not start new addition while already adding', async () => {
      const serviceName = 'Window Washing';
      const token = 'test-token';

      let resolveAddService: (value: any) => void = () => {};
      const addServicePromise = new Promise(resolve => {
        resolveAddService = resolve;
      });

      mockFetch.mockReturnValueOnce(addServicePromise);

      const { result } = renderHook(() => useAddService(mockOnSuccess, mockOnError));

      // Start first addition
      const firstAddPromise = result.current.addService(serviceName, token);

      // Wait for first addition to start
      await waitFor(() => {
        expect(result.current.isAdding).toBe(true);
      });

      // Try to start second addition
      const secondResult = await result.current.addService('Gutter Cleaning', token);
      expect(secondResult).toBe(false);

      // Only first fetch should have been called
      expect(mockFetch).toHaveBeenCalledTimes(1);

      // Resolve first addition
      resolveAddService({
        ok: true,
        json: async () => ({ ok: true }),
      });

