    id: 'rec123',
    quoteId: 'Q-001',
    token: 'test-token',
    firstName: 'John',
    lastName: 'Doe',
    email: 'john@example.com',
    city: 'Test City',
    alaCarteTotal: 200,
    handldTotal: 140,
  },
  lineItems: [
    {
      id: 'rec456',
      service: 'Window Washing',
      handldRate: 70,
      alaCarteRate: 100,
      chosenFrequency: 1,
      quoteId: 'Q-001',
    },
    {
      id: 'rec789',
      service: 'Gutter Cleaning',
      handldRate: 80,
      alaCarteRate: 120,
      chosenFrequency: 1,
      quoteId: 'Q-001',
